-- FIN-08 Slalom, 1v1 e secondo tiratore (idempotente)
insert into public.exercises (id, data, updated_at) values ('5eed0000-0000-4000-8000-00000000013d', '{"code":"FIN-08","title":"Finishing & 1v1 – Slalom, 1v1 e secondo tiratore","area":"finalizzazione","fase":["centrale"],"obiettivi":["conduzione","cambi di direzione","dribbling","marcatura","velocità","tiro"],"eta":"U9-U12","giocatori":"3 file (attaccanti, difensori, secondi tiratori) + portiere","spazio":"Metà campo con porta","durata":12,"materiale":"4 coni arancioni, 5 paletti rossi, 1 manichino, porta, palloni (fila A e fila B con palla)","perche":"Conduzione con cambio di direzione sul manichino, lettura del 1v1 e finalizzazione sotto pressione; il secondo tiratore allena la conclusione rapida su seconda palla. Il difensore lavora su rapidità nello slalom e chiusura.","descrizione":"Setup: fila A (attaccanti, con palla) sui 4 coni arancioni a sinistra; fila B (difensori, con palla) dietro i 5 paletti rossi sul lato destro, in diagonale; manichino al centro vicino al cerchio di centrocampo; giocatore 3 (secondo tiratore) sul vertice sinistro dell’area con la sua fila dietro; portiere in porta.\nEsecuzione: 1 (fila A) parte dai coni e conduce verso il manichino; 2 (fila B) parte in contemporanea e fa lo slalom tra i paletti. 1 aggira il manichino e attacca la porta; 2 esce dallo slalom e chiude: 1v1 sul limite dell’area. 1 conclude in porta, subito dopo conclude 3 (secondo tiratore).\nRitmo continuo, recupero = rotazione in fila.","rotazione":"1: dopo il tiro va in fila dietro al secondo tiratore. 2: dopo il 1v1 va in fila dietro al giocatore 4 (fila paletti). 3: dopo il tiro recupera e torna in fila A sui coni (da verificare: nel video la rotazione non è chiara). Al giro successivo parte per primo il giocatore 4 dalla fila B.","varianti":"Tocchi limitati dopo il manichino. Tiro solo in area o anche da fuori. 2 difende al 100% o al 50%. Tempo massimo di conclusione 3–4″.","coaching":"1: conduzione veloce, cambio di direzione stretto sul manichino, testa alta per leggere da che parte arriva 2. 2: appoggi rapidi nello slalom, uscita aggressiva, chiusura sul lato forte. 3: pronto al tiro appena conclude 1, senza aspettare.","fonte":"Video drill (inviato da Andrea, 23/10/2026)","diagram":{"field":{"preset":"metacampo","w":36,"h":36},"steps":[{"title":"Partenza","note":"1 conduce verso il manichino, 2 fa lo slalom tra i paletti"},{"title":"Manichino e uscita","note":"1 aggira il manichino, 2 esce dallo slalom e chiude"},{"title":"1v1","note":"1v1 sul limite dell’area"},{"title":"Tiro di 1","note":""},{"title":"Secondo tiratore","note":"3 conclude subito dopo"},{"title":"Fine"}],"items":[{"id":"it1073","type":"gk","pos":{"0":{"x":35,"y":18}}},{"id":"it1074","type":"cone","pos":{"0":{"x":1,"y":4}}},{"id":"it1075","type":"cone","pos":{"0":{"x":3,"y":4}}},{"id":"it1076","type":"cone","pos":{"0":{"x":5,"y":4}}},{"id":"it1077","type":"cone","pos":{"0":{"x":7,"y":4}}},{"id":"it1078","type":"pole","pos":{"0":{"x":10,"y":31}}},{"id":"it1079","type":"pole","pos":{"0":{"x":12,"y":29.5}}},{"id":"it1080","type":"pole","pos":{"0":{"x":14,"y":28}}},{"id":"it1081","type":"pole","pos":{"0":{"x":16,"y":26.5}}},{"id":"it1082","type":"pole","pos":{"0":{"x":18,"y":25}}},{"id":"it1083","type":"mannequin","pos":{"0":{"x":9,"y":18}}},{"id":"it1084","type":"playerA","label":"1","pos":{"0":{"x":3,"y":6},"1":{"x":7,"y":15},"2":{"x":11,"y":20},"3":{"x":22,"y":16}}},{"id":"it1085","type":"playerA","label":"A","pos":{"0":{"x":1,"y":7.5}}},{"id":"it1086","type":"playerB","label":"2","pos":{"0":{"x":8,"y":33},"1":{"x":17,"y":27.5},"2":{"x":20.5,"y":22},"3":{"x":24,"y":19}}},{"id":"it1087","type":"playerB","label":"4","pos":{"0":{"x":6,"y":34.5}}},{"id":"it1088","type":"playerA","label":"3","pos":{"0":{"x":23,"y":6.5}}},{"id":"it1089","type":"playerA","label":"3","pos":{"0":{"x":20.5,"y":3.8}}},{"id":"it1090","type":"ball","pos":{"0":{"x":3.6,"y":6.4},"1":{"x":7.6,"y":15.4},"2":{"x":11.6,"y":20.4},"3":{"x":22.6,"y":16.4},"4":{"x":35.6,"y":16.8}}},{"id":"it1091","type":"ball","pos":{"0":{"x":23.6,"y":7},"5":{"x":35.6,"y":20}}}],"arrows":[{"id":"ar1092","kind":"dribble","step":0,"from":{"x":3,"y":6},"to":{"x":7,"y":15}},{"id":"ar1093","kind":"run","step":0,"from":{"x":8,"y":33},"to":{"x":17,"y":27.5},"curve":1.2},{"id":"ar1094","kind":"dribble","step":1,"from":{"x":7,"y":15},"to":{"x":11,"y":20},"curve":-2.5},{"id":"ar1095","kind":"run","step":1,"from":{"x":17,"y":27.5},"to":{"x":20.5,"y":22}},{"id":"ar1096","kind":"dribble","step":2,"from":{"x":11,"y":20},"to":{"x":22,"y":16}},{"id":"ar1097","kind":"run","step":2,"from":{"x":20.5,"y":22},"to":{"x":24,"y":19}},{"id":"ar1098","kind":"shot","step":3,"from":{"x":22.6,"y":16.4},"to":{"x":35.6,"y":16.8}},{"id":"ar1099","kind":"shot","step":4,"from":{"x":23.6,"y":7},"to":{"x":35.6,"y":20}}]},"id":"5eed0000-0000-4000-8000-00000000013d","updatedAt":"2026-10-01T00:00:00.000Z"}'::jsonb, now()) on conflict (id) do nothing;
